import sys,hashlib
p=sys.argv[1];s=open(p,encoding='utf-8').read()
JS="/* ===== MODE MONDIAL : la croix (← → le monde francophone · ↑ ↓ les médias) ===== */\nconst IPTV='https://iptv-org.github.io/iptv/';\nconst AFR=['sn','ci','cm','cd','cg','ml','bf','ne','tg','bj','ga','gn','mg','td','cf','rw','bi','dj','km'];\nconst MONDE_REG=[\n {n:'Monde entier',f:'🌐',tv:['languages/fra'],rq:['language=french'],tout:1},\n {n:'France',f:'🇫🇷',tv:['countries/fr'],rq:['countrycode=FR'],tout:1},\n {n:'Belgique',f:'🇧🇪',tv:['countries/be'],rq:['countrycode=BE&language=french']},\n {n:'Suisse',f:'🇨🇭',tv:['countries/ch'],rq:['countrycode=CH&language=french']},\n {n:'Québec · Canada',f:'🇨🇦',tv:['countries/ca'],rq:['countrycode=CA&language=french']},\n {n:'Luxembourg · Monaco',f:'🇱🇺',tv:['countries/lu','countries/mc'],rq:['countrycode=LU&language=french','countrycode=MC']},\n {n:'Afrique',f:'🌍',tv:AFR.map(c=>'countries/'+c),rq:AFR.map(c=>'countrycode='+c.toUpperCase())},\n {n:'Maghreb',f:'🇲🇦',tv:['countries/ma','countries/dz','countries/tn'],rq:['countrycode=MA&language=french','countrycode=DZ&language=french','countrycode=TN&language=french']},\n {n:'Outre-mer · Caraïbes',f:'🏝️',tv:['re','gp','mq','gf','yt','pf','nc','ht'].map(c=>'countries/'+c),rq:['RE','GP','MQ','GF','YT','PF','NC','PM','HT'].map(c=>'countrycode='+c)}];\nconst MONDE_MED=[{id:'tv',n:'TV',f:'📺'},{id:'radio',n:'Radio',f:'📻'},{id:'musique',n:'Musique',f:'🎵'},{id:'video',n:'Vidéos',f:'🎞️'},{id:'k7',n:'Cassettes',f:'📼'}];\nconst GENRES=[['Chanson','chanson'],['Variété','pop'],['Rap','rap'],['Jazz','jazz'],['Classique','classical'],['Zouk','zouk'],['Afro','afrobeat'],['Rock','rock'],['Électro','electronic'],['Reggae','reggae'],['Années 80','80s'],['Gospel','gospel']];\nlet mX=0,mY=0,mG=0,mondeListe=[],zapListe=null;const mCache=new Map();let fraSet=null;\nasync function m3u(chemin){try{const r=await fetch(IPTV+chemin+'.m3u');const t=await r.text();return t.includes('#EXTINF')?parseM3U(t):[]}catch(e){return []}}\nasync function chargeFra(){if(fraSet)return fraSet;fraSet=new Set((await m3u('languages/fra')).map(x=>x.u));return fraSet}\nasync function mondeTV(reg){const listes=await Promise.all(reg.tv.map(m3u));let L=[],vus=new Set();for(const t of listes)for(const x of t)if(!vus.has(x.u)){vus.add(x.u);L.push(x)}\n if(!reg.tout){const F=await chargeFra();const fr=L.filter(x=>F.has(x.u));if(fr.length)L=fr}return L}\nasync function mondeRadio(reg,tag){const qs=reg.rq.map(q=>q+(tag?'&tag='+encodeURIComponent(tag):''));const lim=reg.rq.length>1?'limit=150&':'limit=1000&';\n const res=await Promise.all(qs.map(q=>chercheRadios(lim+q)));const vus=new Set(),L=[];for(const t of res)for(const x of t)if(!vus.has(x.u)){vus.add(x.u);L.push(x)}return L}\nfunction rendMonde(){const reg=MONDE_REG[mX],med=MONDE_MED[mY];\n const h=$('#mHoriz');h.innerHTML='';MONDE_REG.forEach((r,i)=>{const b=document.createElement('div');b.className='mCase'+(i===mX?' on':'');b.innerHTML='<span class=\"mIco\">'+r.f+'</span><span>'+echap(r.n)+'</span>';b.onclick=()=>{mX=i;rendMonde();mondeCharge()};h.append(b)});\n const v=$('#mVert');v.innerHTML='';MONDE_MED.forEach((m,i)=>{const b=document.createElement('div');b.className='mCase'+(i===mY?' on':'');b.innerHTML='<span class=\"mIco\">'+m.f+'</span><span>'+m.n+'</span>';b.onclick=()=>{mY=i;rendMonde();mondeCharge()};v.append(b)});\n const sel=h.children[mX];if(sel){sel.scrollIntoView({block:'nearest',inline:'center'});v.style.left=Math.max(0,sel.offsetLeft-h.scrollLeft+sel.offsetWidth/2-75)+'px'}\n const g=$('#mGenres');g.style.display=med.id==='musique'?'flex':'none';g.innerHTML='';if(med.id==='musique')GENRES.forEach(([n],i)=>{const b=document.createElement('button');b.textContent=n;if(i===mG)b.className='on';b.onclick=()=>{mG=i;rendMonde();mondeCharge()};g.append(b)});\n $('#mTitre').textContent=reg.f+' '+reg.n+'  ×  '+med.f+' '+med.n+(med.id==='musique'?' · '+GENRES[mG][0]:'')}\nasync function mondeCharge(){const reg=MONDE_REG[mX],med=MONDE_MED[mY],cle=mX+'|'+mY+'|'+(med.id==='musique'?mG:'');const box=$('#mGrille');\n if(med.id==='video'){mondeListe=videos;$('#mInfo').innerHTML='Tes vidéos · YouTube francophone sans pub dans FreeTube · médiathèque Kodi. <button data-l2=\"freetube\">▶ FreeTube</button> <button data-l2=\"kodi\">🎬 Kodi</button> <button id=\"mOuvrir\">📂 Ouvrir des vidéos</button>';\n  $$('[data-l2]').forEach(b=>b.onclick=()=>R.lancer(b.dataset.l2));$('#mOuvrir').onclick=()=>fileIn.click();remplirMonde(box,videos);return}\n if(med.id==='k7'){$('#mInfo').textContent='Tes cassettes enregistrées (repasse dans VLC).';box.innerHTML='';await chargeK7();if(!cassettes.length){box.innerHTML='<div class=\"vide\">Pas encore de cassette.</div>';return}\n  for(const c of cassettes){const d=document.createElement('div');d.className='tuile';d.innerHTML='<div class=\"nm\">📼 '+echap(etiquette(c.n))+'</div><div class=\"st\">'+(c.taille/1e6).toFixed(0)+' Mo</div>';d.onclick=()=>R.lancer('vlc',c.f);box.append(d)}return}\n $('#mInfo').textContent='Recherche sur le réseau mondial…';box.innerHTML='<div class=\"vide\">⏳</div>';\n let L=mCache.get(cle);if(!L){L=med.id==='tv'?await mondeTV(reg):await mondeRadio(reg,med.id==='musique'?GENRES[mG][1]:null);mCache.set(cle,L)}\n if(cle!==mX+'|'+mY+'|'+(MONDE_MED[mY].id==='musique'?mG:''))return;\n mondeListe=L;$('#mInfo').textContent=L.length+' résultat(s). Clique pour lancer · ↑↓ pendant la lecture pour zapper dans cette sélection.';remplirMonde(box,L)}\nfunction remplirMonde(box,L){box.innerHTML='';if(!L.length){box.innerHTML='<div class=\"vide\">Rien trouvé sur ce croisement pour le moment.</div>';return}\n const fr=document.createDocumentFragment();for(const x of L){const d=tuile(x);d.onclick=()=>{zapListe=L;joue(x)};fr.append(d)}box.append(fr)}\ndocument.addEventListener('keydown',e=>{if(page!=='monde'||$('#lecteur').classList.contains('on')||/^(INPUT|SELECT|TEXTAREA)$/.test(e.target.tagName))return;\n const k=e.key;if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter'].includes(k))return;e.preventDefault();\n if(k==='ArrowLeft')mX=(mX-1+MONDE_REG.length)%MONDE_REG.length;else if(k==='ArrowRight')mX=(mX+1)%MONDE_REG.length;\n else if(k==='ArrowUp')mY=(mY-1+MONDE_MED.length)%MONDE_MED.length;else if(k==='ArrowDown')mY=(mY+1)%MONDE_MED.length;\n else if(k==='Enter'&&mondeListe[0]){zapListe=mondeListe;joue(mondeListe[0]);return}\n rendMonde();clearTimeout(mT);mT=setTimeout(mondeCharge,450)});\nlet mT=null;\n"
HTML=" <div class=\"page\" id=\"p-monde\">\n  <h2>🌍 Mode mondial <small>← → le monde francophone · ↑ ↓ les médias · Entrée lance le premier</small></h2>\n  <div id=\"mCroix\"><div id=\"mHoriz\"></div><div id=\"mVert\"></div></div>\n  <div id=\"mTitre\"></div><div id=\"mGenres\"></div><div id=\"mInfo\" class=\"vide\"></div>\n  <div class=\"grille\" id=\"mGrille\"></div>\n </div>\n"
CSS="/* mode mondial : la croix */\n#mCroix{position:relative;height:330px;margin:6px 0 10px}\n#mHoriz{display:flex;gap:10px;overflow-x:auto;padding:8px 2px;position:absolute;top:0;left:0;right:0;scrollbar-width:none}\n#mVert{position:absolute;top:96px;width:150px;display:flex;flex-direction:column;gap:6px;pointer-events:none}\n#mVert .mCase{pointer-events:auto}\n.mCase{flex:0 0 auto;min-width:130px;display:flex;flex-direction:column;align-items:center;gap:4px;padding:8px 10px;border-radius:12px;background:var(--p1);border:1px solid #232838;cursor:pointer;opacity:.55;transition:all .15s;font-size:13px;text-align:center}\n.mCase.on{opacity:1;border-color:var(--a);background:#2a0d14;transform:scale(1.08)}\n#mVert .mCase{min-width:0;flex-direction:row;justify-content:center;padding:5px 8px}\n#mVert .mCase:nth-child(1){margin-top:0}\n.mIco{font-size:24px}\n#mTitre{font:17px Consolas,monospace;color:var(--g);text-shadow:0 0 5px #33ff6688;margin:6px 0}\n#mGenres{display:none;gap:6px;flex-wrap:wrap;margin:6px 0}#mGenres button.on{border-color:var(--a);background:#2a0d14}\n"
R=[('<button data-p="conf">Réglages</button>','<button data-p="monde">🌍 Mode mondial</button><button data-p="conf">Réglages</button>'),
('<div class="page" id="p-conf">',HTML+'<div class="page" id="p-conf">'),
('</style>',CSS+'</style>'),
('/* ===== démarrage ===== */',JS+'\n/* ===== démarrage ===== */'),
("function zappe(d){if(!cur)return;const L=cur.t==='radio'?listeRadio():cur.t==='video'?videos:listeTV();",
 "function zappe(d){if(!cur)return;const L=(zapListe&&zapListe.some(y=>y.u===cur.u))?zapListe:cur.t==='radio'?listeRadio():cur.t==='video'?videos:listeTV();"),
("if(p==='conf')rendConf()}","if(p==='conf')rendConf();if(p==='monde'){rendMonde();mondeCharge()}}"),
("if(cur===x)bandeau('['+x.num+'] RADIO · '","if(cur===x)bandeau((x.num!=null?'['+x.num+'] ':'')+'RADIO · '")]
if 'p-monde' in s: print('DEJA EN v3.2 : rien a faire'); sys.exit(0)
